global proc string[] GP2ut_getCsvAllData(string $fileName){
	int $fileId = `fopen $fileName "r"`;
	string $line = `fgetline $fileId`;		//最上段は不要（目次）
	int $i=0;
	string $IDlist[];
	while ( size( $line ) > 0 ){
		$IDlist[$i] = $line;
		$line = `fgetline $fileId`;
		$i++;
	}
	fclose $fileId;
	return( $IDlist );
}
@end
